autoRefreshWorkerConfig.script:
let timerId = null;
let lastRefreshTime = Date.now();
self.onmessage = function(e) {
    if (e.data === 'START_TIMER' && timerId === null) {
        if (Date.now() - lastRefreshTime > 60000) {
            self.postMessage('REFRESH_DATA');
        }

        timerId = setInterval(function () {
            self.postMessage('REFRESH_DATA');
            lastRefreshTime = Date.now();
        }, 60000);
    } else if (e.data === 'STOP_TIMER' && timerId !== null) {
        clearInterval(timerId);
        timerId = null;
    }
};

